// Cost Radar pricing — pure functions over the bundled Seoul on-demand price table.
// 비용 레이더 가격 계산 — 내장된 서울 리전 온디맨드 가격표 위의 순수 함수.
// Table is generated by scripts/tools/build-price-table.py (Pricing API is blocked by SCP).
import prices from './prices.ap-northeast-2.json';
import { PRICE_AS_OF } from './price-as-of';
import type { UnpricedReason } from './types';

export const HOURS_PER_MONTH = 730;
const REGION = 'ap-northeast-2';
const GP3_BASE_IOPS = 3000;
const GP3_BASE_THROUGHPUT = 125; // MB/s

export type PriceResult = { monthly: number } | { monthly: null; reason: UnpricedReason };

interface Table {
  asOf: string;
  ec2: Record<string, number>;
  ebs: { gbMonth: Record<string, number>; gp3IopsMonth: number; gp3ThroughputMbpsMonth: number; ioIopsMonth: Record<string, number> };
  snapshotGbMonth: number;
  publicIpv4Hour: number;
  natHour: number;
  lbHour: { application: number; network: number };
  vpcEndpointHour: number;
  rds: { instances: Record<string, Record<string, [number, number]>>; storageGbMonth: Record<string, [number, number]> };
  elasticache: Record<string, number>;
}
const T = prices as unknown as Table;

const ok = (monthly: number): PriceResult => ({ monthly });
const no = (reason: UnpricedReason): PriceResult => ({ monthly: null, reason });
const hourly = (rate: number) => ok(rate * HOURS_PER_MONTH);

/** Price list date (YYYY-MM-DD) shown in the UI footer. / 화면에 표시할 가격표 기준일. */
export function priceAsOf(): string {
  return PRICE_AS_OF;
}

export function priceEc2(p: { instanceType: string; platformDetails: string; tenancy: string; region: string }): PriceResult {
  if (p.region !== REGION) return no('other-region');
  if (p.platformDetails !== 'Linux/UNIX') return no('non-linux');
  if (p.tenancy !== 'default') return no('dedicated');
  const rate = T.ec2[p.instanceType];
  return rate === undefined ? no('unknown-type') : hourly(rate);
}

export function priceEbs(p: { volumeType: string; sizeGb: number; iops?: number | null; throughput?: number | null; region: string }): PriceResult {
  if (p.region !== REGION) return no('other-region');
  const perGb = T.ebs.gbMonth[p.volumeType];
  if (perGb === undefined) return no('unknown-type');
  let monthly = p.sizeGb * perGb;
  if (p.volumeType === 'gp3') {
    // Only IOPS/throughput above the free baseline are billed. / 기본 제공량 초과분만 과금.
    monthly += Math.max(0, (p.iops ?? 0) - GP3_BASE_IOPS) * T.ebs.gp3IopsMonth;
    monthly += Math.max(0, (p.throughput ?? 0) - GP3_BASE_THROUGHPUT) * T.ebs.gp3ThroughputMbpsMonth;
  } else if (p.volumeType === 'io1' || p.volumeType === 'io2') {
    monthly += (p.iops ?? 0) * T.ebs.ioIopsMonth[p.volumeType];
  }
  return ok(monthly);
}

/** Uses the volume size, so this is an upper bound (snapshots are incremental). / 볼륨 크기 기준이라 상한값. */
export function priceSnapshot(p: { sizeGb: number; region: string }): PriceResult {
  if (p.region !== REGION) return no('other-region');
  return ok(p.sizeGb * T.snapshotGbMonth);
}

export function pricePublicIp(p: { region: string }): PriceResult {
  return p.region !== REGION ? no('other-region') : hourly(T.publicIpv4Hour);
}

export function priceNat(p: { region: string }): PriceResult {
  return p.region !== REGION ? no('other-region') : hourly(T.natHour);
}

/** Hourly charge only, LCU/NLCU excluded. / 시간당 기본요금만 (LCU/NLCU 제외). */
export function priceLb(p: { type: 'application' | 'network'; region: string }): PriceResult {
  return p.region !== REGION ? no('other-region') : hourly(T.lbHour[p.type]);
}

export function priceVpcEndpoint(p: { azCount: number; region: string }): PriceResult {
  return p.region !== REGION ? no('other-region') : hourly(T.vpcEndpointHour * p.azCount);
}

// Steampipe engine name -> price table key / Steampipe 엔진명 -> 가격표 키
const RDS_ENGINES: Record<string, string> = {
  postgres: 'postgresql',
  mysql: 'mysql',
  mariadb: 'mariadb',
  'aurora-postgresql': 'aurora-postgresql',
  'aurora-mysql': 'aurora-mysql',
  aurora: 'aurora-mysql',
};

/**
 * Instance hours plus allocated storage. Aurora storage is usage-based, so it is not added.
 * A stopped instance pays storage only (so a stopped Aurora instance is 0).
 * 인스턴스 시간 + 할당 스토리지. Aurora 스토리지는 사용량 기반이라 더하지 않는다.
 * 중지된 인스턴스는 스토리지만 (중지된 Aurora는 0).
 */
export function priceRds(p: {
  engine: string; instanceClass: string; multiAz: boolean; storageType: string;
  allocatedGb: number; iops?: number | null; region: string; stopped?: boolean;
}): PriceResult {
  if (p.region !== REGION) return no('other-region');
  const key = RDS_ENGINES[p.engine];
  if (!key) return no('unknown-type');
  const idx = p.multiAz ? 1 : 0;
  let monthly = 0;
  if (!p.stopped) {
    const pair = T.rds.instances[key]?.[p.instanceClass];
    if (!pair) return no('unknown-type');
    monthly = pair[idx] * HOURS_PER_MONTH;
  }
  if (!key.startsWith('aurora-')) {
    const storage = T.rds.storageGbMonth[p.storageType === 'io2' ? 'io1' : p.storageType];
    if (!storage) return no('unknown-type');
    monthly += p.allocatedGb * storage[idx];
  }
  return ok(monthly);
}

/** Redis list price (Valkey is ~20% cheaper, so this is an upper bound for Valkey). / Redis 단가 기준. */
export function priceElastiCache(p: { nodeType: string; nodes: number; region: string }): PriceResult {
  if (p.region !== REGION) return no('other-region');
  const rate = T.elasticache[p.nodeType];
  return rate === undefined ? no('unknown-type') : hourly(rate * p.nodes);
}
